        return value, end + 2
    return None


def _autolink_at(text: str, start: int) -> tuple[str, int] | None:
    if text[start:start + 1] != "<":
        return None
    end = text.find(">", start + 1)
    if end < 0:
        return None
    value = text[start + 1:end]
    uri = _URI_AUTOLINK.fullmatch(value)
    email = _EMAIL_AUTOLINK.fullmatch(value)
