    if start >= len(text):
        return None
    if text[start] == "<":
        end = start + 1
        escaped = False
        while end < len(text):
            if escaped:
                escaped = False
            elif text[end] == "\\":
                escaped = True
            elif text[end] == ">":
                value = text[start + 1:end]
                if "\n" not in value and "\r" not in value and "<" not in value and ">" not in value:
                    return value, end + 1
                return None
            end += 1
        return None
    depth = 0
    end = start
    escaped = False
    while end < len(text):
        char = text[end]
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char in " \t\r\n":
            break
        elif char == "(":
            depth += 1
        elif char == ")":
            if depth == 0:
                break
            depth -= 1
        end += 1
    if end == start or depth:
        return None
    return text[start:end], end


def _title(text: str, start: int) -> tuple[str, int] | None:
    if start >= len(text) or text[start] not in "\"'(":
        return None
    opener = text[start]
    closer = ")" if opener == "(" else opener
    end = start + 1
    escaped = False
    while end < len(text):
        char = text[end]
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == closer:
            return text[start + 1:end], end + 1
        end += 1
    return None


def _link_suffix(text: str, start: int) -> tuple[str, str | None, int] | None:
    if start >= len(text) or text[start] != "(":
        return None
    cursor = start + 1
    while cursor < len(text) and text[cursor] in " \t\r\n":
        cursor += 1
    if cursor < len(text) and text[cursor] == ")":
        return "", None, cursor + 1
    destination = _balanced_destination(text, cursor)
    if destination is None:
        return None
    url, cursor = destination
    whitespace = cursor
    while cursor < len(text) and text[cursor] in " \t\r\n":
        cursor += 1
    title = None
    if cursor != whitespace:
        parsed_title = _title(text, cursor)
        if parsed_title is not None:
            title, cursor = parsed_title
            while cursor < len(text) and text[cursor] in " \t\r\n":
                cursor += 1
    if cursor >= len(text) or text[cursor] != ")":
        return None
    return url, title, cursor + 1


